
"use client";

import { useEffect, useRef, useMemo, useCallback, useState } from "react";

interface Globe3DProps {
  className?: string;
  height?: string | number;
  quality?: "low" | "medium" | "high";
  autoRotate?: boolean;
  rotationSpeed?: number;
  interactive?: boolean;
}

interface City {
  lat: number;
  lon: number;
  label: string;
  traffic: number;
  active: boolean;
}


const CITIES: City[] = [
  { lat: 40.7, lon: -74.0, label: "NYC", traffic: 0.9, active: true },
  { lat: 51.5, lon: -0.1, label: "LON", traffic: 0.8, active: true },
  { lat: 35.7, lon: 139.7, label: "TKO", traffic: 0.7, active: true },
  { lat: 37.8, lon: -122.4, label: "SFO", traffic: 0.6, active: true },
  { lat: 28.6, lon: 77.2, label: "DEL", traffic: 0.5, active: false },
  { lat: 31.2, lon: 121.5, label: "SHA", traffic: 0.7, active: true },
  { lat: 33.9, lon: -118.4, label: "LAX", traffic: 0.4, active: false },
  { lat: 41.9, lon: 12.5, label: "ROM", traffic: 0.3, active: false },
  { lat: 55.8, lon: 37.6, label: "MOS", traffic: 0.6, active: true },
  { lat: -23.6, lon: -46.6, label: "SAO", traffic: 0.5, active: false },
  { lat: -33.9, lon: 151.2, label: "SYD", traffic: 0.4, active: false },
  { lat: 1.35, lon: 103.8, label: "SIN", traffic: 0.8, active: true },
  { lat: 25.2, lon: 55.3, label: "DXB", traffic: 0.7, active: true },
  { lat: 52.5, lon: 13.4, label: "BER", traffic: 0.3, active: false },
  { lat: 48.9, lon: 2.35, label: "PAR", traffic: 0.6, active: true },
  { lat: 39.9, lon: 116.4, label: "BJS", traffic: 0.5, active: false },
  { lat: 19.4, lon: -99.1, label: "MEX", traffic: 0.4, active: false },
  { lat: 30.0, lon: 31.2, label: "CAI", traffic: 0.3, active: false },
  { lat: -26.2, lon: 28.0, label: "JNB", traffic: 0.2, active: false },
  { lat: 6.5, lon: 3.4, label: "LOS", traffic: 0.3, active: false },
  { lat: 22.5, lon: 114.1, label: "HKG", traffic: 0.7, active: true },
];


const generateContinents = () => {
  const continents = [
    
    { lat: 45, lon: -100, size: 15 },
    { lat: 40, lon: -80, size: 10 },
    { lat: 35, lon: -90, size: 12 },
    { lat: 30, lon: -85, size: 8 },
    
    { lat: 50, lon: 10, size: 10 },
    { lat: 45, lon: 5, size: 8 },
    { lat: 55, lon: 15, size: 6 },
    
    { lat: 35, lon: 100, size: 20 },
    { lat: 40, lon: 110, size: 15 },
    { lat: 30, lon: 80, size: 12 },
    
    { lat: 0, lon: 20, size: 15 },
    { lat: -10, lon: 25, size: 10 },
    { lat: -20, lon: 30, size: 8 },
    
    { lat: -25, lon: 135, size: 8 },
    
    { lat: -15, lon: -60, size: 12 },
    { lat: -25, lon: -55, size: 10 },
  ];
  return continents;
};


const generateTrafficData = () => {
  const connections: {
    from: number;
    to: number;
    intensity: number;
    active: boolean;
  }[] = [];
  const numConnections = Math.floor(Math.random() * 12) + 8;

  for (let i = 0; i < numConnections; i++) {
    const from = Math.floor(Math.random() * CITIES.length);
    let to = Math.floor(Math.random() * CITIES.length);
    while (to === from) to = Math.floor(Math.random() * CITIES.length);
    connections.push({
      from,
      to,
      intensity: 0.2 + Math.random() * 0.8,
      active: Math.random() > 0.3,
    });
  }

  return connections;
};


const generateFibonacciSphere = (
  numPoints: number,
): { lat: number; lon: number; value: number }[] => {
  const points: { lat: number; lon: number; value: number }[] = [];
  const phi = Math.PI * (3 - Math.sqrt(5));

  for (let i = 0; i < numPoints; i++) {
    const y = 1 - (i / (numPoints - 1)) * 2;
    const radius = Math.sqrt(1 - y * y);
    const theta = phi * i;

    const x = Math.cos(theta) * radius;
    const z = Math.sin(theta) * radius;

    const lat = Math.asin(y) * (180 / Math.PI);
    const lon = Math.atan2(z, x) * (180 / Math.PI);
    points.push({
      lat,
      lon,
      value: 0.2 + Math.random() * 0.8,
    });
  }

  return points;
};

export default function Globe3D({
  className = "",
  height = "100%",
  quality = "high",
  autoRotate = true,
  rotationSpeed = 0.001,
  interactive = true,
}: Globe3DProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const lastTimeRef = useRef<number>(0);
  const rotationRef = useRef<number>(0);
  const isVisibleRef = useRef<boolean>(true);
  const timeRef = useRef<number>(0);

  
  const isDraggingRef = useRef<boolean>(false);
  const previousMouseRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const targetRotationRef = useRef<number>(0);
  const targetTiltRef = useRef<number>(0);
  const currentRotationRef = useRef<number>(0);
  const currentTiltRef = useRef<number>(0);
  const velocityRef = useRef<number>(0);
  const tiltVelocityRef = useRef<number>(0);

  
  const connections = useMemo(() => generateTrafficData(), []);
  const continents = useMemo(() => generateContinents(), []);

  const gridPoints = useMemo(() => {
    const pointCounts = { low: 300, medium: 800, high: 2000 };
    const count = pointCounts[quality];
    return generateFibonacciSphere(count);
  }, [quality]);

  const getScreenPosition = useCallback(
    (
      lat: number,
      lon: number,
      centerX: number,
      centerY: number,
      radius: number,
      rotation: number,
      tilt: number = 0.1,
    ) => {
      const phi = ((90 - lat) * Math.PI) / 180;
      const theta = (lon * Math.PI) / 180;

      const rotTheta = theta + rotation;

      const tiltCos = Math.cos(tilt);
      const tiltSin = Math.sin(tilt);

      const x = radius * Math.sin(phi) * Math.cos(rotTheta);
      const y = radius * Math.cos(phi);
      const z = radius * Math.sin(phi) * Math.sin(rotTheta);

      const tiltedY = y * tiltCos - z * tiltSin;
      const tiltedZ = y * tiltSin + z * tiltCos;

      return {
        x: centerX + x,
        y: centerY + tiltedY,
        z: tiltedZ,
        rawX: x,
        rawY: tiltedY,
        rawZ: tiltedZ,
      };
    },
    [],
  );

  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d", {
      alpha: true,
      willReadFrequently: false,
    });
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = canvas.parentElement?.getBoundingClientRect();
    const width = rect?.width || 600;
    const h =
      typeof height === "number" ? height : parseInt(height as string) || 500;

    canvas.width = width * dpr;
    canvas.height = h * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${h}px`;
    ctx.scale(dpr, dpr);

    const centerX = width / 2;
    const centerY = h / 2;
    const radius = Math.min(width, h) * 0.38;

    
    const handleMouseDown = (e: MouseEvent) => {
      if (!interactive) return;
      isDraggingRef.current = true;
      previousMouseRef.current = { x: e.clientX, y: e.clientY };
      canvas.style.cursor = "grabbing";
    };

    const handleMouseMove = (e: MouseEvent) => {
      if (!interactive) return;

      if (isDraggingRef.current) {
        const deltaX = e.clientX - previousMouseRef.current.x;
        const deltaY = e.clientY - previousMouseRef.current.y;

        
        targetRotationRef.current += deltaX * 0.005;
        targetTiltRef.current += deltaY * 0.003;

        
        targetTiltRef.current = Math.max(
          -0.5,
          Math.min(0.5, targetTiltRef.current),
        );

        previousMouseRef.current = { x: e.clientX, y: e.clientY };

        
        velocityRef.current = deltaX * 0.002;
        tiltVelocityRef.current = deltaY * 0.002;
      }
    };

    const handleMouseUp = () => {
      if (!interactive) return;
      isDraggingRef.current = false;
      canvas.style.cursor = "grab";
    };

    const handleMouseLeave = () => {
      if (!interactive) return;
      isDraggingRef.current = false;
      canvas.style.cursor = "grab";
    };

    const handleMouseEnter = () => {
      if (!interactive) return;
      canvas.style.cursor = "grab";
    };

    
    let touchStartX = 0;
    let touchStartY = 0;
    let isTouching = false;

    const handleTouchStart = (e: TouchEvent) => {
      if (!interactive) return;
      const touch = e.touches[0];
      if (touch) {
        isTouching = true;
        touchStartX = touch.clientX;
        touchStartY = touch.clientY;
        previousMouseRef.current = { x: touch.clientX, y: touch.clientY };
      }
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (!interactive || !isTouching) return;
      e.preventDefault();
      const touch = e.touches[0];
      if (touch) {
        const deltaX = touch.clientX - previousMouseRef.current.x;
        const deltaY = touch.clientY - previousMouseRef.current.y;

        targetRotationRef.current += deltaX * 0.005;
        targetTiltRef.current += deltaY * 0.003;
        targetTiltRef.current = Math.max(
          -0.5,
          Math.min(0.5, targetTiltRef.current),
        );

        previousMouseRef.current = { x: touch.clientX, y: touch.clientY };
        velocityRef.current = deltaX * 0.002;
        tiltVelocityRef.current = deltaY * 0.002;
      }
    };

    const handleTouchEnd = () => {
      if (!interactive) return;
      isTouching = false;
    };

    
    canvas.addEventListener("mousedown", handleMouseDown);
    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleMouseUp);
    canvas.addEventListener("mouseleave", handleMouseLeave);
    canvas.addEventListener("mouseenter", handleMouseEnter);
    canvas.addEventListener("touchstart", handleTouchStart, { passive: true });
    canvas.addEventListener("touchmove", handleTouchMove, { passive: false });
    canvas.addEventListener("touchend", handleTouchEnd, { passive: true });

    
    const trafficPulses: {
      startTime: number;
      duration: number;
      from: number;
      to: number;
      intensity: number;
    }[] = [];

    const generatePulse = () => {
      if (connections.length === 0) return;
      const activeConns = connections.filter((c) => c.active);
      if (activeConns.length === 0) return;

      const conn = activeConns[Math.floor(Math.random() * activeConns.length)];
      trafficPulses.push({
        startTime: timeRef.current,
        duration: 1.5 + Math.random() * 2,
        from: conn.from,
        to: conn.to,
        intensity: 0.5 + Math.random() * 0.5,
      });

      if (trafficPulses.length > 30) trafficPulses.shift();
    };

    for (let i = 0; i < 8; i++) {
      setTimeout(generatePulse, i * 400);
    }

    const pulseInterval = setInterval(
      generatePulse,
      600 + Math.random() * 1000,
    );

    
    const observer = new IntersectionObserver(
      ([entry]) => {
        isVisibleRef.current = entry.isIntersecting;
        if (!entry.isIntersecting && animationRef.current) {
          cancelAnimationFrame(animationRef.current);
          animationRef.current = null;
        } else if (entry.isIntersecting && !animationRef.current) {
          lastTimeRef.current = performance.now();
          animationRef.current = requestAnimationFrame(animate);
        }
      },
      { threshold: 0.1 },
    );
    observer.observe(canvas);

    const animate = (timestamp: number) => {
      if (!isVisibleRef.current) {
        animationRef.current = null;
        return;
      }

      const delta = Math.min(timestamp - lastTimeRef.current, 50);
      lastTimeRef.current = timestamp;
      timeRef.current += delta / 1000;

      
      if (!isDraggingRef.current) {
        velocityRef.current *= 0.98;
        tiltVelocityRef.current *= 0.98;

        
        if (Math.abs(velocityRef.current) < 0.0001) {
          velocityRef.current = 0;
        }
        if (Math.abs(tiltVelocityRef.current) < 0.0001) {
          tiltVelocityRef.current = 0;
        }

        targetRotationRef.current += velocityRef.current;
        targetTiltRef.current += tiltVelocityRef.current;
        targetTiltRef.current = Math.max(
          -0.5,
          Math.min(0.5, targetTiltRef.current),
        );
      }

      
      if (
        autoRotate &&
        !isDraggingRef.current &&
        Math.abs(velocityRef.current) < 0.001
      ) {
        currentRotationRef.current += rotationSpeed * (delta / 16);
      }

      
      const rotDiff = targetRotationRef.current - currentRotationRef.current;
      currentRotationRef.current += rotDiff * 0.08;

      
      const tiltDiff = targetTiltRef.current - currentTiltRef.current;
      currentTiltRef.current += tiltDiff * 0.08;

      const finalRotation = currentRotationRef.current;
      const finalTilt = currentTiltRef.current;

      ctx.clearRect(0, 0, width, h);

      
      const bgGlow = ctx.createRadialGradient(
        centerX,
        centerY,
        0,
        centerX,
        centerY,
        radius * 1.8,
      );
      bgGlow.addColorStop(0, "rgba(34, 229, 122, 0.03)");
      bgGlow.addColorStop(0.5, "rgba(34, 229, 122, 0.015)");
      bgGlow.addColorStop(1, "rgba(0, 0, 0, 0)");
      ctx.fillStyle = bgGlow;
      ctx.fillRect(0, 0, width, h);

      
      
      const outerGlow = ctx.createRadialGradient(
        centerX,
        centerY,
        radius * 0.85,
        centerX,
        centerY,
        radius * 1.15,
      );
      outerGlow.addColorStop(0, "rgba(34, 229, 122, 0)");
      outerGlow.addColorStop(0.7, "rgba(34, 229, 122, 0.02)");
      outerGlow.addColorStop(0.9, "rgba(34, 229, 122, 0.06)");
      outerGlow.addColorStop(1, "rgba(34, 229, 122, 0)");
      ctx.fillStyle = outerGlow;
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius * 1.15, 0, Math.PI * 2);
      ctx.fill();

      
      for (let i = 0; i < 3; i++) {
        const rimAngle = finalRotation * 0.5 + i * 2.1;
        const rimX = centerX + radius * 0.95 * Math.cos(rimAngle);
        const rimY =
          centerY +
          radius * 0.85 * Math.sin(rimAngle) +
          currentTiltRef.current * 20;
        const rimGrad = ctx.createRadialGradient(
          rimX,
          rimY,
          0,
          rimX,
          rimY,
          radius * 0.4,
        );
        rimGrad.addColorStop(0, `rgba(34, 229, 122, ${0.02 + i * 0.01})`);
        rimGrad.addColorStop(1, "rgba(34, 229, 122, 0)");
        ctx.fillStyle = rimGrad;
        ctx.beginPath();
        ctx.arc(rimX, rimY, radius * 0.4, 0, Math.PI * 2);
        ctx.fill();
      }

      
      ctx.strokeStyle = "rgba(34, 229, 122, 0.08)";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.stroke();

      
      continents.forEach((cont) => {
        const pos = getScreenPosition(
          cont.lat,
          cont.lon,
          centerX,
          centerY,
          radius,
          finalRotation,
          finalTilt,
        );
        if (pos.z > -0.1) {
          const size = cont.size * (0.8 + (0.4 * (pos.z / radius + 1)) / 2);
          const alpha = 0.03 + (0.04 * (pos.z / radius + 1)) / 2;

          ctx.fillStyle = `rgba(34, 229, 122, ${alpha})`;
          ctx.strokeStyle = `rgba(34, 229, 122, ${alpha * 0.3})`;
          ctx.lineWidth = 0.5;

          ctx.beginPath();
          ctx.ellipse(pos.x, pos.y, size * 0.8, size * 0.5, 0, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }
      });

      
      ctx.strokeStyle = "rgba(34, 229, 122, 0.02)";
      ctx.lineWidth = 0.3;

      for (let lat = -70; lat <= 70; lat += 15) {
        const phi = ((90 - lat) * Math.PI) / 180;
        ctx.beginPath();
        let first = true;
        for (let lon = 0; lon <= 360; lon += 1) {
          const theta = (lon * Math.PI) / 180;
          const x =
            centerX + radius * Math.sin(phi) * Math.cos(theta + finalRotation);
          const y =
            centerY + radius * Math.cos(phi) + currentTiltRef.current * 20;
          const z = radius * Math.sin(phi) * Math.sin(theta + finalRotation);

          if (z > -0.2) {
            if (first) {
              ctx.moveTo(x, y);
              first = false;
            } else ctx.lineTo(x, y);
          } else {
            first = true;
          }
        }
        ctx.stroke();
      }

      
      gridPoints.forEach((point) => {
        const pos = getScreenPosition(
          point.lat,
          point.lon,
          centerX,
          centerY,
          radius,
          finalRotation,
          finalTilt,
        );
        if (pos.z > -0.05) {
          const depthFactor = (pos.z / radius + 1) / 2;
          const size = 0.5 + point.value * 1.5 * (0.3 + 0.7 * depthFactor);
          const baseOpacity = 0.05 + point.value * 0.2;
          const opacity = baseOpacity * (0.3 + 0.7 * depthFactor);

          
          const g = 150 + 105 * point.value;
          const b = 50 + 50 * point.value;

          ctx.fillStyle = `rgba(34, ${g}, ${b}, ${opacity})`;
          ctx.beginPath();
          ctx.arc(pos.x, pos.y, size, 0, Math.PI * 2);
          ctx.fill();

          if (point.value > 0.7 && pos.z > 0.2) {
            ctx.fillStyle = `rgba(34, 229, 122, ${0.02 * depthFactor})`;
            ctx.beginPath();
            ctx.arc(pos.x, pos.y, size * 3, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      });

      
      connections.forEach((conn) => {
        const fromCity = CITIES[conn.from];
        const toCity = CITIES[conn.to];
        const from = getScreenPosition(
          fromCity.lat,
          fromCity.lon,
          centerX,
          centerY,
          radius,
          finalRotation,
          finalTilt,
        );
        const to = getScreenPosition(
          toCity.lat,
          toCity.lon,
          centerX,
          centerY,
          radius,
          finalRotation,
          finalTilt,
        );

        if (from.z > -0.2 || to.z > -0.2) {
          const avgZ = (from.z + to.z) / 2;
          const depthFactor = (avgZ / radius + 1) / 2;

          const midX = (from.x + to.x) / 2;
          const midY = (from.y + to.y) / 2;
          const distance = Math.sqrt(
            Math.pow(to.x - from.x, 2) + Math.pow(to.y - from.y, 2),
          );

          const arcHeight = distance * 0.15 + 15 * (1 + conn.intensity * 0.5);
          const cpX = midX;
          const cpY = midY - arcHeight * (0.3 + 0.7 * (avgZ > 0 ? 1 : 0.5));

          const gradient = ctx.createLinearGradient(from.x, from.y, to.x, to.y);
          const baseAlpha = (0.03 + conn.intensity * 0.06) * depthFactor;
          const activeAlpha = conn.active ? baseAlpha * 1.5 : baseAlpha * 0.5;

          gradient.addColorStop(0, `rgba(34, 229, 122, ${activeAlpha * 0.5})`);
          gradient.addColorStop(
            0.5,
            `rgba(34, 229, 122, ${activeAlpha * 1.5})`,
          );
          gradient.addColorStop(1, `rgba(34, 229, 122, ${activeAlpha * 0.5})`);

          ctx.beginPath();
          ctx.moveTo(from.x, from.y);
          ctx.quadraticCurveTo(cpX, cpY, to.x, to.y);
          ctx.strokeStyle = gradient;
          ctx.lineWidth = 0.3 + conn.intensity * 0.8 * depthFactor;
          ctx.stroke();

          if (conn.active && depthFactor > 0.3) {
            ctx.shadowColor = `rgba(34, 229, 122, ${0.02 * depthFactor})`;
            ctx.shadowBlur = 15;
            ctx.stroke();
            ctx.shadowBlur = 0;
          }
        }
      });

      
      trafficPulses.forEach((pulse) => {
        const elapsed = timeRef.current - pulse.startTime;
        const progress = Math.min(elapsed / pulse.duration, 1);

        if (progress < 1) {
          const fromCity = CITIES[pulse.from];
          const toCity = CITIES[pulse.to];
          const from = getScreenPosition(
            fromCity.lat,
            fromCity.lon,
            centerX,
            centerY,
            radius,
            finalRotation,
            finalTilt,
          );
          const to = getScreenPosition(
            toCity.lat,
            toCity.lon,
            centerX,
            centerY,
            radius,
            finalRotation,
            finalTilt,
          );

          if (from.z > -0.2 || to.z > -0.2) {
            const avgZ = (from.z + to.z) / 2;
            const depthFactor = (avgZ / radius + 1) / 2;

            if (depthFactor > 0.1) {
              const t = progress * progress * (3 - 2 * progress);

              const midX = (from.x + to.x) / 2;
              const midY = (from.y + to.y) / 2;
              const distance = Math.sqrt(
                Math.pow(to.x - from.x, 2) + Math.pow(to.y - from.y, 2),
              );
              const arcHeight = distance * 0.15 + 15;
              const cpX = midX;
              const cpY = midY - arcHeight;

              const mt = 1 - t;
              const x = mt * mt * from.x + 2 * mt * t * cpX + t * t * to.x;
              const y = mt * mt * from.y + 2 * mt * t * cpY + t * t * to.y;

              const intensity = pulse.intensity * depthFactor;
              const pulseSize = 3 + 5 * intensity * (1 - progress);

              
              const glow = ctx.createRadialGradient(
                x,
                y,
                0,
                x,
                y,
                pulseSize * 3,
              );
              glow.addColorStop(
                0,
                `rgba(34, 229, 122, ${0.3 * intensity * (1 - progress)})`,
              );
              glow.addColorStop(
                0.3,
                `rgba(34, 229, 122, ${0.15 * intensity * (1 - progress)})`,
              );
              glow.addColorStop(1, "rgba(34, 229, 122, 0)");
              ctx.fillStyle = glow;
              ctx.beginPath();
              ctx.arc(x, y, pulseSize * 3, 0, Math.PI * 2);
              ctx.fill();

              
              ctx.fillStyle = `rgba(34, 229, 122, ${0.6 * intensity * (1 - progress * 0.3)})`;
              ctx.shadowColor = `rgba(34, 229, 122, ${0.2 * intensity})`;
              ctx.shadowBlur = 20;
              ctx.beginPath();
              ctx.arc(x, y, pulseSize, 0, Math.PI * 2);
              ctx.fill();
              ctx.shadowBlur = 0;

              
              for (let i = 1; i < 8; i++) {
                const trailProgress = Math.max(0, t - i * 0.03);
                if (trailProgress > 0) {
                  const mt2 = 1 - trailProgress;
                  const tx =
                    mt2 * mt2 * from.x +
                    2 * mt2 * trailProgress * cpX +
                    trailProgress * trailProgress * to.x;
                  const ty =
                    mt2 * mt2 * from.y +
                    2 * mt2 * trailProgress * cpY +
                    trailProgress * trailProgress * to.y;
                  const trailSize = pulseSize * (1 - i / 8) * 0.5;
                  ctx.fillStyle = `rgba(34, 229, 122, ${0.05 * intensity * (1 - i / 8)})`;
                  ctx.beginPath();
                  ctx.arc(tx, ty, trailSize, 0, Math.PI * 2);
                  ctx.fill();
                }
              }
            }
          }
        }
      });

      
      CITIES.forEach((city) => {
        const pos = getScreenPosition(
          city.lat,
          city.lon,
          centerX,
          centerY,
          radius,
          finalRotation,
          finalTilt,
        );
        if (pos.z > 0.1) {
          const depthFactor = (pos.z / radius + 1) / 2;
          const isActive = city.active;
          const traffic = city.traffic;

          
          const glowSize = isActive ? 15 + traffic * 10 : 8;
          const glowAlpha = isActive ? 0.05 + traffic * 0.05 : 0.02;

          const cityGlow = ctx.createRadialGradient(
            pos.x,
            pos.y,
            0,
            pos.x,
            pos.y,
            glowSize * depthFactor,
          );
          cityGlow.addColorStop(
            0,
            `rgba(34, 229, 122, ${glowAlpha * depthFactor})`,
          );
          cityGlow.addColorStop(1, "rgba(34, 229, 122, 0)");
          ctx.fillStyle = cityGlow;
          ctx.beginPath();
          ctx.arc(pos.x, pos.y, glowSize * depthFactor, 0, Math.PI * 2);
          ctx.fill();

          
          const dotSize = isActive ? 2.5 + traffic * 1.5 : 1.5;
          const dotColor = isActive
            ? `rgba(34, 229, 122, ${0.4 + traffic * 0.4})`
            : "rgba(34, 229, 122, 0.2)";

          ctx.fillStyle = dotColor;
          ctx.shadowColor = isActive
            ? `rgba(34, 229, 122, ${0.1 * traffic})`
            : "transparent";
          ctx.shadowBlur = isActive ? 10 : 0;
          ctx.beginPath();
          ctx.arc(pos.x, pos.y, dotSize * depthFactor, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;

          
          if (width > 600 && pos.z > 0.3 && (isActive || quality === "high")) {
            ctx.font = `${isActive ? 8 : 6}px -apple-system, system-ui, sans-serif`;
            ctx.textAlign = "center";
            ctx.textBaseline = "bottom";

            const labelAlpha = isActive ? 0.3 + traffic * 0.2 : 0.1;
            ctx.fillStyle = `rgba(34, 229, 122, ${labelAlpha})`;
            ctx.fillText(city.label, pos.x, pos.y - dotSize * depthFactor - 4);
          }
        }
      });

      
      for (let i = 0; i < 5; i++) {
        const angle = finalRotation * 0.7 + i * 1.26 + timeRef.current * 0.2;
        const orbitRadius =
          radius * (1.02 + 0.03 * Math.sin(timeRef.current * 0.3 + i));
        const x = centerX + orbitRadius * Math.cos(angle);
        const y =
          centerY +
          orbitRadius * Math.sin(angle) * 0.4 +
          currentTiltRef.current * 20;
        const z = orbitRadius * Math.sin(angle) * 0.8;

        if (z > -radius * 0.2) {
          const depthFactor = (z / radius + 1) / 2;
          const size =
            0.5 + Math.sin(timeRef.current * 0.5 + i * 1.5) * 0.3 + 0.5;
          const alpha =
            0.03 +
            0.05 *
              depthFactor *
              (0.5 + 0.5 * Math.sin(timeRef.current * 0.3 + i));

          ctx.fillStyle = `rgba(34, 229, 122, ${alpha})`;
          ctx.shadowColor = `rgba(34, 229, 122, ${alpha * 0.3})`;
          ctx.shadowBlur = 5;
          ctx.beginPath();
          ctx.arc(x, y, size * depthFactor, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;
        }
      }

      
      if (quality !== "low") {
        const numParticles = quality === "high" ? 50 : 25;
        for (let i = 0; i < numParticles; i++) {
          const particleAngle = i * 0.75 + timeRef.current * 0.02;
          const particleRad =
            radius * (0.85 + 0.15 * Math.sin(i * 1.7 + timeRef.current * 0.1));
          const x =
            centerX +
            particleRad * Math.cos(particleAngle + finalRotation * 0.3);
          const y =
            centerY +
            particleRad *
              0.7 *
              Math.sin(particleAngle * 0.6 + finalRotation * 0.2) +
            currentTiltRef.current * 15;
          const z =
            particleRad *
            0.4 *
            Math.sin(particleAngle * 0.5 + timeRef.current * 0.05);

          if (z > -radius * 0.1) {
            const size =
              0.3 +
              0.5 * (0.5 + 0.5 * Math.sin(i * 2.3 + timeRef.current * 0.2));
            const alpha =
              0.01 +
              0.02 * (0.5 + 0.5 * Math.sin(i * 1.1 + timeRef.current * 0.1));

            ctx.fillStyle = `rgba(34, 229, 122, ${alpha})`;
            ctx.beginPath();
            ctx.arc(x, y, size, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }

      
      const lightX = centerX + radius * 0.5;
      const lightY = centerY - radius * 0.3 + currentTiltRef.current * 20;
      const lightGrad = ctx.createRadialGradient(
        lightX,
        lightY,
        0,
        lightX,
        lightY,
        radius * 1.5,
      );
      lightGrad.addColorStop(0, "rgba(34, 229, 122, 0.02)");
      lightGrad.addColorStop(0.5, "rgba(34, 229, 122, 0.01)");
      lightGrad.addColorStop(1, "rgba(34, 229, 122, 0)");
      ctx.fillStyle = lightGrad;
      ctx.beginPath();
      ctx.arc(lightX, lightY, radius * 1.5, 0, Math.PI * 2);
      ctx.fill();

      const ambientGlow = ctx.createRadialGradient(
        centerX,
        centerY,
        radius * 0.2,
        centerX,
        centerY,
        radius,
      );
      ambientGlow.addColorStop(0, "rgba(34, 229, 122, 0.01)");
      ambientGlow.addColorStop(1, "rgba(34, 229, 122, 0)");
      ctx.fillStyle = ambientGlow;
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.fill();

      animationRef.current = requestAnimationFrame(animate);
    };

    lastTimeRef.current = performance.now();
    animationRef.current = requestAnimationFrame(animate);

    const handleResize = () => {
      const newRect = canvas.parentElement?.getBoundingClientRect();
      if (!newRect) return;
      const newWidth = newRect.width || 600;
      const newHeight =
        typeof height === "number" ? height : parseInt(height as string) || 500;

      canvas.width = newWidth * dpr;
      canvas.height = newHeight * dpr;
      canvas.style.width = `${newWidth}px`;
      canvas.style.height = `${newHeight}px`;
      ctx.scale(dpr, dpr);
    };

    window.addEventListener("resize", handleResize);

    return () => {
      observer.disconnect();
      clearInterval(pulseInterval);
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
      canvas.removeEventListener("mousedown", handleMouseDown);
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
      canvas.removeEventListener("mouseleave", handleMouseLeave);
      canvas.removeEventListener("mouseenter", handleMouseEnter);
      canvas.removeEventListener("touchstart", handleTouchStart);
      canvas.removeEventListener("touchmove", handleTouchMove);
      canvas.removeEventListener("touchend", handleTouchEnd);
      window.removeEventListener("resize", handleResize);
    };
  }, [
    height,
    quality,
    autoRotate,
    rotationSpeed,
    interactive,
    connections,
    gridPoints,
    continents,
    getScreenPosition,
  ]);

  return (
    <div
      className={`relative w-full h-full flex items-center justify-center overflow-hidden ${className}`}
    >
      <canvas
        ref={canvasRef}
        className="w-full h-full select-none"
        style={{ touchAction: "none" }}
      />
    </div>
  );
}
