"use client";

import { motion } from "framer-motion";
import {
  Database,
  Globe,
  Network,
  Users,
  Shield,
  Zap,
  Server,
  Activity,
} from "lucide-react";
import Skeleton from "./Skeleton";

interface StatsProps {
  countries: number;
  asns: number;
  networks: number;
  loading?: boolean;
}

export default function Stats({
  countries,
  asns,
  networks,
  loading = false,
}: StatsProps) {
  const stats = [
    {
      label: "Countries",
      value: countries,
      icon: Globe,
      color: "text-[#22e57a]",
      bg: "bg-[rgba(34,229,122,.1)]",
      border: "border-[rgba(34,229,122,.15)]",
      description: "Nation coverage",
    },
    {
      label: "ASNs",
      value: asns,
      icon: Network,
      color: "text-[#5c8aff]",
      bg: "bg-[rgba(92,138,255,.1)]",
      border: "border-[rgba(92,138,255,.15)]",
      description: "Autonomous Systems",
    },
    {
      label: "Networks",
      value: networks,
      icon: Server,
      color: "text-[#a78bfa]",
      bg: "bg-[rgba(167,139,250,.1)]",
      border: "border-[rgba(167,139,250,.15)]",
      description: "IP ranges",
    },
    {
      label: "Uptime",
      value: "99.9",
      icon: Activity,
      color: "text-[#f59e0b]",
      bg: "bg-[rgba(245,158,11,.1)]",
      border: "border-[rgba(245,158,11,.15)]",
      description: "Reliability",
      suffix: "%",
    },
  ];

  if (loading) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[...Array(4)].map((_, i) => (
          <Skeleton key={i} className="h-28 w-full" variant="card" />
        ))}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      {stats.map((stat, index) => (
        <motion.div
          key={stat.label}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: index * 0.08 }}
          whileHover={{ y: -4 }}
          className={`bg-[#070b09]/80 backdrop-blur-sm border ${stat.border} rounded-xl p-5 text-center transition-all duration-300 hover:shadow-[0_20px_60px_rgba(34,229,122,.04)]`}
        >
          <div
            className={`w-11 h-11 ${stat.bg} rounded-xl flex items-center justify-center mx-auto mb-3`}
          >
            <stat.icon className={stat.color} size={20} />
          </div>
          <div
            className={`text-2xl md:text-3xl font-bold font-mono ${stat.color}`}
          >
            {typeof stat.value === "number"
              ? stat.value.toLocaleString()
              : stat.value}
            {stat.suffix || ""}
          </div>
          <div className="text-sm font-medium text-[#6f8a7d] mt-0.5">
            {stat.label}
          </div>
          {stat.description && (
            <div className="text-[10px] font-mono text-[#4f6459] mt-1">
              {stat.description}
            </div>
          )}
        </motion.div>
      ))}
    </div>
  );
}
